// src/shared/log.ts
var SECRET_ENV_NAMES = /(TOKEN|SECRET|KEY|PASSWORD|CREDENTIAL)/i;
var SECRET_PATTERNS = [
  /\bBearer\s+[A-Za-z0-9._~+/-]+=*/g,
  /\bya29\.[A-Za-z0-9._-]+/g,
  /\b1\/\/[A-Za-z0-9._-]{20,}/g,
  /\bAIza[0-9A-Za-z_-]{35}\b/g,
  /("?(?:access_token|refresh_token|id_token|client_secret|api_key|code_verifier)"?\s*[:=]\s*"?)[^"&\s,}]+/gi
];
var MASK = "[REDACTED]";
function redact(text, env = process.env) {
  let out = text;
  for (const [name, value] of Object.entries(env)) {
    if (value && value.length >= 8 && SECRET_ENV_NAMES.test(name) && !name.endsWith("_PATH")) {
      out = out.split(value).join(MASK);
    }
  }
  for (const pattern of SECRET_PATTERNS) {
    out = out.replace(
      pattern,
      (match, prefix) => typeof prefix === "string" && match.startsWith(prefix) ? `${prefix}${MASK}` : MASK
    );
  }
  return out;
}
var log = {
  info(message) {
    process.stderr.write(`${redact(message)}
`);
  },
  warn(message) {
    process.stderr.write(`Warning: ${redact(message)}
`);
  },
  error(message) {
    process.stderr.write(`${redact(message)}
`);
  }
};
function printJson(value) {
  process.stdout.write(`${redact(JSON.stringify(value, null, 2))}
`);
}

